insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('2sa-18-22','2sa','사무엘하',18,22,'사독의 아들 아히마아스가 다시 요압에게 이르되 청하건대 아무쪼록 내가 또한 구스 사람의 뒤를 따라 달려가게 하소서 하니 요압이 이르되 내 아들아 너는 왜 달려가려 하느냐 이 소식으로 말미암아서는 너는 상을 받지 못하리라 하되',8501),
('2sa-18-23','2sa','사무엘하',18,23,'그가 한사코 달려가겠노라 하는지라 요압이 이르되 그리하라 하니 아히마아스가 들길로 달음질하여 구스 사람보다 앞질러가니라',8502),
('2sa-18-24','2sa','사무엘하',18,24,'때에 다윗이 두 문 사이에 앉아 있더라 파수꾼이 성 문 위층에 올라가서 눈을 들어 보니 어떤 사람이 홀로 달려오는지라',8503),
('2sa-18-25','2sa','사무엘하',18,25,'파수꾼이 외쳐 왕께 아뢰매 왕이 이르되 그가 만일 혼자면 그의 입에 소식이 있으리라 할 때에 그가 점점 가까이 오니라',8504),
('2sa-18-26','2sa','사무엘하',18,26,'파수꾼이 본즉 한 사람이 또 달려오는지라 파수꾼이 문지기에게 외쳐 이르되 보라 한 사람이 또 혼자 달려온다 하니 왕이 이르되 그도 소식을 가져오느니라',8505),
('2sa-18-27','2sa','사무엘하',18,27,'파수꾼이 이르되 내가 보기에는 앞선 사람의 달음질이 사독의 아들 아히마아스의 달음질과 같으니이다 하니 왕이 이르되 그는 좋은 사람이니 좋은 소식을 가져오느니라 하니라',8506),
('2sa-18-28','2sa','사무엘하',18,28,'아히마아스가 외쳐 왕께 아뢰되 평강하옵소서 하고 왕 앞에서 얼굴을 땅에 대고 절하며 이르되 왕의 하나님 여호와를 찬양하리로소이다 그의 손을 들어 내 주 왕을 대적하는 자들을 넘겨 주셨나이다 하니',8507),
('2sa-18-29','2sa','사무엘하',18,29,'왕이 이르되 젊은 압살롬은 잘 있느냐 하니라 아히마아스가 대답하되 요압이 왕의 종 나를 보낼 때에 크게 소동하는 것을 보았사오나 무슨 일인지 알지 못하였나이다 하니',8508),
('2sa-18-30','2sa','사무엘하',18,30,'왕이 이르되 물러나 거기 서 있으라 하매 물러나서 서 있더라',8509),
('2sa-18-31','2sa','사무엘하',18,31,'구스 사람이 이르러 말하되 내 주 왕께 아뢸 소식이 있나이다 여호와께서 오늘 왕을 대적하던 모든 원수를 갚으셨나이다 하니',8510),
('2sa-18-32','2sa','사무엘하',18,32,'왕이 구스 사람에게 묻되 젊은 압살롬은 잘 있느냐 구스 사람이 대답하되 내 주 왕의 원수와 일어나서 왕을 대적하는 자들은 다 그 청년과 같이 되기를 원하나이다 하니',8511),
('2sa-18-33','2sa','사무엘하',18,33,'왕의 마음이 심히 아파 문 위층으로 올라가서 우니라 그가 올라갈 때에 말하기를 내 아들 압살롬아 내 아들 내 아들 압살롬아 차라리 내가 너를 대신하여 죽었더면, 압살롬 내 아들아 내 아들아 하였더라',8512),
('2sa-19-1','2sa','사무엘하',19,1,'어떤 사람이 요압에게 아뢰되 왕이 압살롬을 위하여 울며 슬퍼하시나이다 하니',8513),
('2sa-19-2','2sa','사무엘하',19,2,'왕이 그 아들을 위하여 슬퍼한다 함이 그 날에 백성들에게 들리매 그 날의 승리가 모든 백성에게 슬픔이 된지라',8514),
('2sa-19-3','2sa','사무엘하',19,3,'그 날에 백성들이 싸움에 쫓겨 부끄러워 도망함 같이 가만히 성읍으로 들어가니라',8515),
('2sa-19-4','2sa','사무엘하',19,4,'왕이 그의 얼굴을 가리고 큰 소리로 부르되 내 아들 압살롬아 압살롬아 내 아들아 내 아들아 하니',8516),
('2sa-19-5','2sa','사무엘하',19,5,'요압이 집에 들어가서 왕께 말씀 드리되 왕께서 오늘 왕의 생명과 왕의 자녀의 생명과 처첩과 비빈들의 생명을 구원한 모든 부하들의 얼굴을 부끄럽게 하시니',8517),
('2sa-19-6','2sa','사무엘하',19,6,'이는 왕께서 미워하는 자는 사랑하시며 사랑하는 자는 미워하시고 오늘 지휘관들과 부하들을 멸시하심을 나타내심이라 오늘 내가 깨달으니 만일 압살롬이 살고 오늘 우리가 다 죽었더면 왕이 마땅히 여기실 뻔하였나이다',8518),
('2sa-19-7','2sa','사무엘하',19,7,'이제 곧 일어나 나가 왕의 부하들의 마음을 위로하여 말씀하옵소서 내가 여호와를 두고 맹세하옵나니 왕이 만일 나가지 아니하시면 오늘 밤에 한 사람도 왕과 함께 머물지 아니할지라 그리하면 그 화가 왕이 젊었을 때부터 지금까지 당하신 모든 화보다 더욱 심하리이다 하니',8519),
('2sa-19-8','2sa','사무엘하',19,8,'왕이 일어나 성문에 앉으매 어떤 사람이 모든 백성에게 말하되 왕이 문에 앉아 계신다 하니 모든 백성이 왕 앞으로 나아오니라. 이스라엘은 이미 각기 장막으로 도망하였더라',8520),
('2sa-19-9','2sa','사무엘하',19,9,'이스라엘 모든 지파 백성들이 변론하여 이르되 왕이 우리를 원수의 손에서 구원하여 내셨고 또 우리를 블레셋 사람들의 손에서 구원하셨으나 이제 압살롬을 피하여 그 땅에서 나가셨고',8521),
('2sa-19-10','2sa','사무엘하',19,10,'우리가 기름을 부어 우리를 다스리게 한 압살롬은 싸움에서 죽었거늘 이제 너희가 어찌하여 왕을 도로 모셔 올 일에 잠잠하고 있느냐 하니라',8522),
('2sa-19-11','2sa','사무엘하',19,11,'다윗 왕이 사독과 아비아달 두 제사장에게 소식을 전하여 이르되 너희는 유다 장로들에게 말하여 이르기를 왕의 말씀이 온 이스라엘이 왕을 왕궁으로 도로 모셔오자 하는 말이 왕께 들렸거늘 너희는 어찌하여 왕을 궁으로 모시는 일에 나중이 되느냐',8523),
('2sa-19-12','2sa','사무엘하',19,12,'너희는 내 형제요 내 골육이거늘 너희는 어찌하여 왕을 도로 모셔오는 일에 나중이 되리요 하셨다 하고',8524),
('2sa-19-13','2sa','사무엘하',19,13,'너희는 또 아마사에게 이르기를 너는 내 골육이 아니냐 네가 요압을 이어서 항상 내 앞에서 지휘관이 되지 아니하면 하나님이 내게 벌 위에 벌을 내리시기를 바라노라 하셨다 하라 하여',8525),
('2sa-19-14','2sa','사무엘하',19,14,'모든 유다 사람들의 마음을 하나 같이 기울게 하매 그들이 왕께 전갈을 보내어 이르되 당신께서는 모든 부하들과 더불어 돌아오소서 한지라',8526),
('2sa-19-15','2sa','사무엘하',19,15,'왕이 돌아와 요단에 이르매 유다 족속이 왕을 맞아 요단을 건너가게 하려고 길갈로 오니라',8527),
('2sa-19-16','2sa','사무엘하',19,16,'바후림에 있는 베냐민 사람 게라의 아들 시므이가 급히 유다 사람과 함께 다윗 왕을 맞으러 내려올 때에',8528),
('2sa-19-17','2sa','사무엘하',19,17,'베냐민 사람 천 명이 그와 함께 하고 사울 집안의 종 시바도 그의 아들 열다섯과 종 스무 명과 더불어 그와 함께 하여 요단 강을 밟고 건너 왕 앞으로 나아오니라',8529),
('2sa-19-18','2sa','사무엘하',19,18,'왕의 가족을 건너가게 하며 왕이 좋게 여기는 대로 쓰게 하려 하여 나룻배로 건너가니 왕이 요단을 건너가게 할 때에 게라의 아들 시므이가 왕 앞에 엎드려',8530),
('2sa-19-19','2sa','사무엘하',19,19,'왕께 아뢰되 내 주여 원하건대 내게 죄를 돌리지 마옵소서 내 주 왕께서 예루살렘에서 나오시던 날에 종의 패역한 일을 기억하지 마시오며 왕의 마음에 두지 마옵소서',8531),
('2sa-19-20','2sa','사무엘하',19,20,'왕의 종 내가 범죄한 줄 아옵기에 오늘 요셉의 온 족속 중 내가 먼저 내려와서 내 주 왕을 영접하나이다 하니',8532),
('2sa-19-21','2sa','사무엘하',19,21,'스루야의 아들 아비새가 대답하여 이르되 시므이가 여호와의 기름 부으신 자를 저주하였으니 그로 말미암아 죽어야 마땅하지 아니하니이까 하니라',8533),
('2sa-19-22','2sa','사무엘하',19,22,'다윗이 이르되 스루야의 아들들아 내가 너희와 무슨 상관이 있기에 너희가 오늘 나의 원수가 되느냐 오늘 어찌하여 이스라엘 가운데에서 사람을 죽이겠느냐 내가 오늘 이스라엘의 왕이 된 것을 내가 알지 못하리요 하고',8534),
('2sa-19-23','2sa','사무엘하',19,23,'왕이 시므이에게 이르되 네가 죽지 아니하리라 하고 그에게 맹세하니라',8535),
('2sa-19-24','2sa','사무엘하',19,24,'사울의 손자 므비보셋이 내려와 왕을 맞으니 그는 왕이 떠난 날부터 평안히 돌아오는 날까지 그의 발을 맵시 내지 아니하며 그의 수염을 깎지 아니하며 옷을 빨지 아니하였더라',8536),
('2sa-19-25','2sa','사무엘하',19,25,'예루살렘에서 와서 왕을 맞을 때에 왕이 그에게 물어 이르되 므비보셋이여 네가 어찌하여 나와 함께 가지 아니하였더냐 하니',8537),
('2sa-19-26','2sa','사무엘하',19,26,'대답하되 내 주 왕이여 왕의 종인 나는 다리를 절므로 내 나귀에 안장을 지워 그 위에 타고 왕과 함께 가려 하였더니 내 종이 나를 속이고',8538),
('2sa-19-27','2sa','사무엘하',19,27,'종인 나를 내 주 왕께 모함하였나이다 내 주 왕께서는 하나님의 사자와 같으시니 왕의 처분대로 하옵소서',8539),
('2sa-19-28','2sa','사무엘하',19,28,'내 아버지의 온 집이 내 주 왕 앞에서는 다만 죽을 사람이 되지 아니하였나이까 그러나 종을 왕의 상에서 음식 먹는 자 가운데에 두셨사오니 내게 아직 무슨 공의가 있어서 다시 왕께 부르짖을 수 있사오리이까 하니라',8540),
('2sa-19-29','2sa','사무엘하',19,29,'왕이 그에게 이르되 네가 어찌하여 또 네 일을 말하느냐 내가 이르노니 너는 시바와 밭을 나누라 하니',8541),
('2sa-19-30','2sa','사무엘하',19,30,'므비보셋이 왕께 아뢰되 내 주 왕께서 평안히 왕궁에 돌아오시게 되었으니 그로 그 전부를 차지하게 하옵소서 하니라',8542),
('2sa-19-31','2sa','사무엘하',19,31,'길르앗 사람 바르실래가 왕이 요단을 건너가게 하려고 로글림에서 내려와 함께 요단에 이르니',8543),
('2sa-19-32','2sa','사무엘하',19,32,'바르실래는 매우 늙어 나이가 팔십 세라 그는 큰 부자이므로 왕이 마하나임에 머물 때에 그가 왕을 공궤하였더라',8544),
('2sa-19-33','2sa','사무엘하',19,33,'왕이 바르실래에게 이르되 너는 나와 함께 건너가자 예루살렘에서 내가 너를 공궤하리라',8545),
('2sa-19-34','2sa','사무엘하',19,34,'바르실래가 왕께 아뢰되 내 생명의 날이 얼마나 있사옵겠기에 어찌 왕과 함께 예루살렘으로 올라가리이까',8546),
('2sa-19-35','2sa','사무엘하',19,35,'내 나이가 이제 팔십 세라 어떻게 좋고 흉한 것을 분간할 수 있사오며 음식의 맛을 알 수 있사오리이까 이 종이 어떻게 다시 노래하는 남자나 여인의 소리를 알아들을 수 있사오리이까 어찌하여 종이 내 주 왕께 아직도 누를 끼치리이까',8547),
('2sa-19-36','2sa','사무엘하',19,36,'당신의 종은 왕을 모시고 요단을 건너려는 것뿐이거늘 왕께서 어찌하여 이같은 상으로 내게 갚으려 하시나이까',8548),
('2sa-19-37','2sa','사무엘하',19,37,'청하건대 당신의 종을 돌려보내옵소서 내가 내 고향 부모의 묘 곁에서 죽으려 하나이다 그러나 왕의 종 김함이 여기 있사오니 청하건대 그가 내 주 왕과 함께 건너가게 하시옵고 왕의 처분대로 그에게 베푸소서 하니라',8549),
('2sa-19-38','2sa','사무엘하',19,38,'왕이 대답하되 김함이 나와 함께 건너가리니 나는 네가 좋아하는 대로 그에게 베풀겠고 또 네가 내게 구하는 것은 다 너를 위하여 시행하리라 하니라',8550),
('2sa-19-39','2sa','사무엘하',19,39,'백성이 다 요단을 건너매 왕도 건너가서 왕이 바르실래에게 입을 맞추고 그에게 복을 비니 그가 자기 곳으로 돌아가니라',8551),
('2sa-19-40','2sa','사무엘하',19,40,'왕이 길갈로 건너오고 김함도 함께 건너오니 온 유다 백성과 이스라엘 백성의 절반이나 왕과 함께 건너니라',8552),
('2sa-19-41','2sa','사무엘하',19,41,'온 이스라엘 사람이 왕께 나아와 왕께 아뢰되 우리 형제 유다 사람들이 어찌 왕을 도둑하여 왕과 왕의 집안과 왕을 따르는 모든 사람을 인도하여 요단을 건너가게 하였나이까 하매',8553),
('2sa-19-42','2sa','사무엘하',19,42,'모든 유다 사람이 이스라엘 사람에게 대답하되 왕은 우리의 종친인 까닭이라 너희가 어찌 이 일에 대하여 분 내느냐 우리가 왕의 것을 조금이라도 얻어 먹었느냐 왕께서 우리에게 선물로 주신 것이 있느냐',8554),
('2sa-19-43','2sa','사무엘하',19,43,'이스라엘 사람이 유다 사람에게 대답하여 이르되 우리는 왕에 대하여 열 몫을 가졌으니 다윗에게 대하여 너희보다 더욱 관계가 있거늘 너희가 어찌 우리를 멸시하여 우리 왕을 모셔 오는 일에 먼저 우리와 의논하지 아니하였느냐 하나 유다 사람의 말이 이스라엘 사람의 말보다 더 강경하였더라',8555),
('2sa-20-1','2sa','사무엘하',20,1,'마침 거기에 불량배 하나가 있으니 그의 이름은 세바인데 베냐민 사람 비그리의 아들이었더라 그가 나팔을 불며 이르되 우리는 다윗과 나눌 분깃이 없으며 이새의 아들에게서 받을 유산이 우리에게 없도다 이스라엘아 각각 장막으로 돌아가라 하매',8556),
('2sa-20-2','2sa','사무엘하',20,2,'이에 온 이스라엘 사람들이 다윗 따르기를 그치고 올라가 비그리의 아들 세바를 따르나 유다 사람들은 그들의 왕과 합하여 요단에서 예루살렘까지 따르니라',8557),
('2sa-20-3','2sa','사무엘하',20,3,'다윗이 예루살렘 본궁에 이르러 전에 머물러 왕궁을 지키게 한 후궁 열 명을 잡아 별실에 가두고 먹을 것만 주고 그들에게 관계하지 아니하니 그들이 죽는 날까지 갇혀서 생과부로 지내니라',8558),
('2sa-20-4','2sa','사무엘하',20,4,'왕이 아마사에게 이르되 너는 나를 위하여 삼 일 내로 유다 사람을 큰 소리로 불러 모으고 너도 여기 있으라 하니라',8559),
('2sa-20-5','2sa','사무엘하',20,5,'아마사가 유다 사람을 모으러 가더니 왕이 정한 기일에 지체된지라',8560),
('2sa-20-6','2sa','사무엘하',20,6,'다윗이 이에 아비새에게 이르되 이제 비그리의 아들 세바가 압살롬보다 우리를 더 해하리니 너는 네 주의 부하들을 데리고 그의 뒤를 쫓아가라 그가 견고한 성읍에 들어가 우리들을 피할까 염려하노라 하매',8561),
('2sa-20-7','2sa','사무엘하',20,7,'요압을 따르는 자들과 그렛 사람들과 블렛 사람들과 모든 용사들이 다 아비새를 따라 비그리의 아들 세바를 뒤쫓으려고 예루살렘에서 나와',8562),
('2sa-20-8','2sa','사무엘하',20,8,'기브온 큰 바위 곁에 이르매 아마사가 맞으러 오니 그 때에 요압이 군복을 입고 띠를 띠고 칼집에 꽂은 칼을 허리에 맸는데 그가 나아갈 때에 칼이 빠져 떨어졌더라',8563),
('2sa-20-9','2sa','사무엘하',20,9,'요압이 아마사에게 이르되 내 형은 평안하냐 하며 오른손으로 아마사의 수염을 잡고 그와 입을 맞추려는 체하매',8564),
('2sa-20-10','2sa','사무엘하',20,10,'아마사가 요압의 손에 있는 칼은 주의하지 아니한지라 요압이 칼로 그의 배를 찌르매 그의 창자가 땅에 쏟아지니 그를 다시 치지 아니하여도 죽으니라. 요압과 그의 동생 아비새가 비그리의 아들 세바를 뒤쫓을새',8565),
('2sa-20-11','2sa','사무엘하',20,11,'요압의 청년 중 하나가 아마사 곁에 서서 이르되 요압을 좋아하는 자가 누구이며 요압을 따라 다윗을 위하는 자는 누구냐 하니',8566),
('2sa-20-12','2sa','사무엘하',20,12,'아마사가 길 가운데 피 속에 놓여 있는지라 그 청년이 모든 백성이 서 있는 것을 보고 아마사를 큰길에서부터 밭으로 옮겼으나 거기에 이르는 자도 다 멈추어 서는 것을 보고 옷을 그 위에 덮으니라',8567),
('2sa-20-13','2sa','사무엘하',20,13,'아마사를 큰길에서 옮겨가매 사람들이 다 요압을 따라 비그리의 아들 세바를 뒤쫓아가니라',8568),
('2sa-20-14','2sa','사무엘하',20,14,'세바가 이스라엘 모든 지파 가운데 두루 다녀서 아벨과 벧마아가와 베림 온 땅에 이르니 그 무리도 다 모여 그를 따르더라',8569),
('2sa-20-15','2sa','사무엘하',20,15,'이에 그들이 벧마아가 아벨로 가서 세바를 에우고 그 성읍을 향한 지역 언덕 위에 토성을 쌓고 요압과 함께 한 모든 백성이 성벽을 쳐서 헐고자 하더니',8570),
('2sa-20-16','2sa','사무엘하',20,16,'그 성읍에서 지혜로운 여인 한 사람이 외쳐 이르되 들을지어다 들을지어다 청하건대 너희는 요압에게 이르기를 이리로 가까이 오라 내가 네게 말하려 하노라 한다 하라',8571),
('2sa-20-17','2sa','사무엘하',20,17,'요압이 그 여인에게 가까이 가니 여인이 이르되 당신이 요압이니이까 하니 대답하되 그러하다 하니라 여인이 그에게 이르되 여종의 말을 들으소서 하니 대답하되 내가 들으리라 하니라',8572),
('2sa-20-18','2sa','사무엘하',20,18,'여인이 말하여 이르되 옛 사람들이 흔히 말하기를 아벨에게 가서 물을 것이라 하고 그 일을 끝내었나이다',8573),
('2sa-20-19','2sa','사무엘하',20,19,'나는 이스라엘의 화평하고 충성된 자 중 하나이거늘 당신이 이스라엘 가운데 어머니 같은 성을 멸하고자 하시는도다 어찌하여 당신이 여호와의 기업을 삼키고자 하시나이까 하니',8574),
('2sa-20-20','2sa','사무엘하',20,20,'요압이 대답하여 이르되 결단코 그렇지 아니하다 결단코 그렇지 아니하다 삼키거나 멸하거나 하려 함이 아니니',8575),
('2sa-20-21','2sa','사무엘하',20,21,'그 일이 그러한 것이 아니니라 에브라임 산지 사람 비그리의 아들 그의 이름을 세바라 하는 자가 손을 들어 왕 다윗을 대적하였나니 너희가 그만 내주면 내가 이 성벽에서 떠나가리라 하니라 여인이 요압에게 이르되 그의 머리를 성벽에서 당신에게 내어던지리이다 하고',8576),
('2sa-20-22','2sa','사무엘하',20,22,'이에 여인이 그의 지혜를 가지고 모든 백성에게 나아가매 그들이 비그리의 아들 세바의 머리를 베어 요압에게 던진지라 이에 요압이 나팔을 불매 무리가 흩어져 성읍에서 물러나 각기 장막으로 돌아가고 요압은 예루살렘으로 돌아와 왕에게 나아가니라',8577),
('2sa-20-23','2sa','사무엘하',20,23,'요압은 이스라엘 온 군대의 지휘관이 되고 여호야다의 아들 브나야는 그렛 사람과 블렛 사람의 지휘관이 되고',8578),
('2sa-20-24','2sa','사무엘하',20,24,'아도람은 감역관이 되고 아힐룻의 아들 여호사밧은 사관이 되고',8579),
('2sa-20-25','2sa','사무엘하',20,25,'스와는 서기관이 되고 사독과 아비아달은 제사장이 되고',8580),
('2sa-20-26','2sa','사무엘하',20,26,'야일 사람 이라는 다윗의 대신이 되니라',8581),
('2sa-21-1','2sa','사무엘하',21,1,'다윗의 시대에 해를 거듭하여 삼 년 기근이 있으므로 다윗이 여호와 앞에 간구하매 여호와께서 이르시되 이는 사울과 피를 흘린 그의 집으로 말미암음이니 그가 기브온 사람을 죽였음이니라 하시니라',8582),
('2sa-21-2','2sa','사무엘하',21,2,'기브온 사람은 이스라엘 족속이 아니요 그들은 아모리 사람 중에서 남은 자라 이스라엘 족속들이 전에 그들에게 맹세하였거늘 사울이 이스라엘과 유다 족속을 위하여 열심이 있으므로 그들을 죽이고자 하였더라 이에 왕이 기브온 사람을 불러 그들에게 물으니라',8583),
('2sa-21-3','2sa','사무엘하',21,3,'다윗이 그들에게 묻되 내가 너희를 위하여 어떻게 하랴 내가 어떻게 속죄하여야 너희가 여호와의 기업을 위하여 복을 빌겠느냐 하니',8584),
('2sa-21-4','2sa','사무엘하',21,4,'기브온 사람이 그에게 대답하되 사울과 그의 집과 우리 사이의 문제는 은금에 있지 아니하오며 이스라엘 가운데에서 사람을 죽이는 문제도 우리에게 있지 아니하니이다 하니라 왕이 이르되 너희가 말하는 대로 시행하리라',8585),
('2sa-21-5','2sa','사무엘하',21,5,'그들이 왕께 아뢰되 우리를 학살하였고 또 우리를 멸하여 이스라엘 영토 내에 머물지 못하게 하려고 모해한 사람의',8586),
('2sa-21-6','2sa','사무엘하',21,6,'자손 일곱 사람을 우리에게 내주소서 여호와께서 택하신 사울의 고을 기브아에서 우리가 그들을 여호와 앞에서 목 매어 달겠나이다 하니 왕이 이르되 내가 내주리라 하니라',8587),
('2sa-21-7','2sa','사무엘하',21,7,'그러나 다윗과 사울의 아들 요나단 사이에 서로 여호와를 두고 맹세한 것이 있으므로 왕이 사울의 손자 요나단의 아들 므비보셋은 아끼고',8588),
('2sa-21-8','2sa','사무엘하',21,8,'왕이 이에 아야의 딸 리스바에게서 난 자 곧 사울의 두 아들 알모니와 므비보셋과 사울의 딸 메랍에게서 난 자 곧 므홀랏 사람 바르실래의 아들 아드리엘의 다섯 아들을 붙잡아',8589),
('2sa-21-9','2sa','사무엘하',21,9,'그들을 기브온 사람의 손에 넘기니 기브온 사람이 그들을 산 위에서 여호와 앞에 목 매어 달매 그들 일곱 사람이 동시에 죽으니 죽은 때는 곡식 베는 첫날 곧 보리를 베기 시작하는 때더라',8590),
('2sa-21-10','2sa','사무엘하',21,10,'아야의 딸 리스바가 굵은 베를 가져다가 자기를 위하여 바위 위에 펴고 곡식 베기 시작할 때부터 하늘에서 비가 시체에 쏟아지기까지 그 시체에 낮에는 공중의 새가 앉지 못하게 하고 밤에는 들짐승이 범하지 못하게 한지라',8591),
('2sa-21-11','2sa','사무엘하',21,11,'이에 아야의 딸 사울의 첩 리스바가 행한 일이 다윗에게 알려지매',8592),
('2sa-21-12','2sa','사무엘하',21,12,'다윗이 가서 사울의 뼈와 그의 아들 요나단의 뼈를 길르앗 야베스 사람에게서 가져가니 이는 전에 블레셋 사람들이 사울을 길보아에서 죽여 블레셋 사람들이 벧산 거리에 매단 것을 그들이 가만히 가져온 것이라',8593),
('2sa-21-13','2sa','사무엘하',21,13,'다윗이 그 곳에서 사울의 뼈와 그의 아들 요나단의 뼈를 가지고 올라오매 사람들이 그 달려 죽은 자들의 뼈를 거두어다가',8594),
('2sa-21-14','2sa','사무엘하',21,14,'사울과 그의 아들 요나단의 뼈와 함께 베냐민 땅 셀라에서 그의 아버지 기스의 묘에 장사하되 모두 왕의 명령을 따라 행하니라 그 후에야 하나님이 그 땅을 위한 기도를 들으시니라',8595),
('2sa-21-15','2sa','사무엘하',21,15,'블레셋 사람이 다시 이스라엘을 치거늘 다윗이 그의 부하들과 함께 내려가서 블레셋 사람과 싸우더니 다윗이 피곤하매',8596),
('2sa-21-16','2sa','사무엘하',21,16,'거인족의 아들 중에 무게가 삼백 세겔 되는 놋 창을 들고 새 칼을 찬 이스비브놉이 다윗을 죽이려 하므로',8597),
('2sa-21-17','2sa','사무엘하',21,17,'스루야의 아들 아비새가 다윗을 도와 그 블레셋 사람들을 쳐죽이니 그 때에 다윗의 추종자들이 그에게 맹세하여 이르되 왕은 다시 우리와 함께 전장에 나가지 마옵소서 이스라엘의 등불이 꺼지지 말게 하옵소서 하니라',8598),
('2sa-21-18','2sa','사무엘하',21,18,'그 후에 다시 블레셋 사람과 곱에서 전쟁할 때에 후사 사람 십브개는 거인족의 아들 중의 삽을 쳐죽였고',8599),
('2sa-21-19','2sa','사무엘하',21,19,'또 다시 블레셋 사람과 곱에서 전쟁할 때에 베들레헴 사람 야레오르김의 아들 엘하난은 가드 골리앗의 아우 라흐미를 죽였는데 그 자의 창 자루는 베틀 채 같았더라',8600),
('2sa-21-20','2sa','사무엘하',21,20,'또 가드에서 전쟁할 때에 그 곳에 키가 큰 자 하나는 손가락과 발가락이 각기 여섯 개씩 모두 스물 네 개가 있는데 그도 거인족의 소생이라',8601),
('2sa-21-21','2sa','사무엘하',21,21,'그가 이스라엘 사람을 능욕하므로 다윗의 형 삼마의 아들 요나단이 그를 죽이니라',8602),
('2sa-21-22','2sa','사무엘하',21,22,'이 네 사람 가드의 거인족의 소생이 다윗의 손과 그의 부하들의 손에 다 넘어졌더라',8603),
